globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-20 21:39:55 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"丸井G、顧客情報延べ1733万件が漏洩　委託先に不正アクセス - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUC209MW0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 19:38","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"丸井グループ、委託先への不正アクセスにより1733万件の顧客情報が漏洩","summary":"丸井グループは、業務委託先であるプレイドが提供するサービス「KARTE」が不正アクセスを受けた影響で、延べ1733万件の顧客情報が漏洩したと発表しました。流出した情報には、ECサイト利用者やエポスカード利用者の氏名、性別、生年月日、メールアドレス、顧客管理番号などが含まれています。\n\n今回の事案は、委託先のシステムが攻撃を受けたことで発生しました。クレジットカード情報の漏洩は確認されていませんが、一部の顧客については年収やキャッシング限度額が含まれる可能性も指摘されています。現在、二次被害の報告はありませんが、企業におけるサプライチェーン全体のセキュリティ管理の重要性が改めて浮き彫りとなりました。","importance":9},{"title":"AIが追加学習なしで自らのウェイトを書き換えて「自分自身を賢くする」ことに成功","url":"https://gigazine.net/news/20261120-large-language-model-can-rewrite-itself/","source":"Hatena","published_at":"2026-11-20 19:11","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIが追加学習なしで自らのウェイトを書き換え性能向上に成功","summary":"イリノイ大学やカーネギーメロン大学の研究チームが、AIモデルが自らの内部ウェイト（重み）を分析・書き換えることで、追加学習なしに性能を向上させる手法を実証しました。従来、AIの性能向上には再学習が必要でしたが、本手法は推論中に自らの問題点を特定し、ウェイトを直接修正するものです。\n\n実験では270億パラメーターのモデルが数学の問題で正答率を向上させたほか、破損したウェイトの修復にも成功しました。この成果は、AIが自律的に能力を高める「再帰的自己改善」に向けた重要な一歩と位置付けられています。今後は、より小規模なモデルでの適用や、数学以外のタスクへの汎用性が期待されます。","importance":9},{"title":"「httpS://」だと暗号化されず平文で送信……「PHP」に約20年潜んでいた脆弱性が解決／問題はいたってシンプル、なんともはや……【やじうまの杜】","url":"https://forest.watch.impress.co.jp/docs/serial/yajiuma/2158241.html","source":"Hatena","published_at":"2026-11-20 18:26","genre":"web","genre_label":"Web開発・言語","headline":"PHPに20年潜んでいた脆弱性、大文字の「HTTPS」で暗号化が解除される欠陥","summary":"PHPにおいて、URLスキームの大文字・小文字を区別する処理の不備により、暗号化通信が平文で送信されてしまう脆弱性が発見されました。具体的には「HTTPS://」のように「S」を大文字で記述すると、TLSによる暗号化がスキップされるというものです。\n\nこの問題は20年以上前から存在しており、パスワードや認証トークンが漏洩するリスクがありました。最新版で修正済みですが、アプリケーション側でURLの正規化を行うなどの回避策も案内されています。長年見過ごされてきたシンプルな実装ミスが、セキュリティに大きな影響を与え得ることを示す事例です。","importance":8},{"title":"dbt v1 でメトリクスを一元管理する未来 〜Apache Ossie と Lightdash で試す〜","url":"https://zenn.dev/kyami/articles/dbt-snowflake-apache-ossie","source":"Zenn","published_at":"2026-11-19 22:48","genre":"other","genre_label":"総合・その他IT","headline":"dbt v1とApache Ossieによるメトリクス一元管理の検証","summary":"dbtで定義したメトリクスをSnowflakeのSemantic Viewに変換し、BIツール（Lightdash）と共有する仕組みを検証したレポート。メトリクスの二重管理を解消し、一元管理を目指す取り組みである。\n\nApache Ossieを介することで、dbtのYAML定義をSnowflakeネイティブのオブジェクトとして利用可能になる。AI（Cortex Analyst）との連携も含め、現在の発展途上な状況と、何が実現可能かを技術的に深掘りしている。","importance":7},{"title":"「あと10年もたないかもしれない」Rubyの父 まつもとゆきひろが危惧するOSS文化の消滅 - エンジニアtype | 転職type","url":"https://type.jp/et/feature/32219/","source":"Hatena","published_at":"2026-11-20 13:31","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"まつもとゆきひろ氏が語る、OSS文化の消滅危機と開発者負担の増大","summary":"Rubyの生みの親であるまつもとゆきひろ氏が、OSS文化の存続に対する危機感を表明しました。AIの普及によりOSSの存在感が希薄化する一方で、相次ぐ脆弱性対応など開発者の負担は増大しており、このままでは文化が10年もたない可能性があると指摘しています。\n\nソフトウェア開発の基盤を支えるOSSへの企業支援の難しさや、エンジニアが直面する未来について語られており、技術コミュニティの持続可能性を考える上で非常に重要な提言となっています。","importance":9},{"title":"RTKの走行データ収集でAndroidの記録アプリを外から監視する","url":"https://zenn.dev/nauh_blog/articles/b60cd6973c8a3f","source":"Zenn","published_at":"2026-11-20 18:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Androidアプリの監視によるRTK走行データの効率的な収集手法","summary":"RTK測位を用いた高精度な走行データ収集において、Androidアプリ「DroggerGPS」の動作を外部から監視する仕組みを構築した事例が紹介されました。走行中に記録が停止しても気づきにくいという課題を解決するため、監視アプリが受信機とアプリの状態を定期的にサーバーへ送信します。\n\nこのシステムにより、リアルタイムでの状態把握と遠隔管理が可能となり、走行のやり直しを減らす効率的なデータ収集を実現しています。Androidのプロセス隔離環境下で、いかにして他アプリの状態を読み取り、安定した監視を行うかという技術的な工夫が解説されています。","importance":5},{"title":"【速報】三井住友銀で情報漏えい、最大1400万件","url":"https://www.47news.jp/15262461.html","source":"Hatena","published_at":"2026-11-20 19:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"三井住友銀行、委託先への不正アクセスで最大1400万件の顧客情報漏洩","summary":"三井住友銀行は、業務委託先であるプレイドのサービスが不正アクセスを受けたことに伴い、最大約1400万件の顧客情報が漏洩した可能性があると発表しました。同社は詳細な被害状況の調査を進めています。\n\n本件は、丸井グループの漏洩事案と同様に、共通の委託先であるプレイドのシステムを標的とした攻撃によるものです。金融機関における顧客情報の管理体制と、委託先を含めたセキュリティリスク管理の脆弱性が改めて問われる事態となっています。","importance":9},{"title":"Microsoftのタスク管理サービス「Microsoft To Do」、突然のサービス終了発表でユーザー動揺【やじうまWatch】","url":"https://internet.watch.impress.co.jp/docs/yajiuma/2158124.html","source":"Hatena","published_at":"2026-11-20 12:27","genre":"other","genre_label":"総合・その他IT","headline":"Microsoft To Doが2027年に終了、Plannerへの統合にユーザーから不満の声","summary":"Microsoftがタスク管理サービス「Microsoft To Do」を2027年6月30日に終了し、「Microsoft Planner」へ統合すると発表した。Wunderlistの系譜を継ぐ人気アプリの終了にユーザーが動揺している。\n\nPlannerにはTo Doの主要機能であるファイル添付やリストグループ機能が不足しており、個人用プランでの利用も制限されている。データ移行の懸念や代替アプリの必要性から、個人ユーザーを中心に強い反発が起きている。","importance":6},{"title":"GeminiがMacを代わりに操作可能に　アプリやファイルをまたぐ作業も自動化","url":"https://japan.cnet.com/article/35255218/","source":"Hatena","published_at":"2026-11-20 15:19","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Mac版Geminiがアプリやファイルを横断して操作する自動化機能を米国で提供開始","summary":"GoogleはMac版Geminiに、ユーザーの指示に基づいてアプリやウェブを操作する新機能を追加しました。ユーザーは文章で指示を出すだけで、Geminiがメニュー選択や文字入力、フォーム記入などを代行し、複数のアプリやファイルをまたぐ作業を自動化できます。\n\n操作はユーザーの承認制で、いつでも一時停止可能な安全設計です。現在は米国の有料プラン加入者向けに提供されており、Appleシリコン搭載のmacOS Sequoia以降で利用可能です。日本での提供時期は未定ですが、AIによるPC操作の自動化が実用段階に入ったことを示す重要な動きです。","importance":9},{"title":"巨大なAPI Gateway用OpenAPI(Swagger)ファイルをTypeSpecで整理整頓","url":"https://zenn.dev/cariot_dev/articles/70944a671647a8","source":"Zenn","published_at":"2026-11-20 17:44","genre":"web","genre_label":"Web開発・言語","headline":"巨大なOpenAPI定義をTypeSpecで整理・リファクタリングする手法","summary":"15,000行を超える巨大なOpenAPI（Swagger）ファイルを、Microsoft製のAPI定義言語「TypeSpec」へ移行した取り組みが紹介されました。TypeScriptライクな構文による高い開発体験と、ファイル分割の容易さが導入の決め手となっています。\n\n移行にあたっては、現行の定義との整合性を保つガードレールを設け、段階的にリファクタリングを進める手法がとられました。また、API Gateway特有のベンダー拡張や、TypeSpecで表現しきれないメソッドの補完方法など、実運用における具体的な課題解決策が示されています。","importance":7},{"title":"斜め上からやってきた「SaaSの死」｜ninoya 古越","url":"https://note.com/aatoku/n/n129df4db50ba","source":"Hatena","published_at":"2026-11-20 13:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"データ流出リスクとAI活用で揺らぐ「SaaSの死」とAXへの転換","summary":"相次ぐ大手企業のSaaS情報流出を受け、顧客データを外部に預けることへの懸念が高まっています。これにより、ロックインを前提とした従来のSaaSビジネスモデルが揺らぎ始めています。\n\n代わって注目されているのが、AIを活用して自社環境でのシステム構築を支援する「AX（AI Transformation）」です。データを外に出さず、プロの支援とAIで安価に構築するモデルは、SaaSの営業コスト構造を根本から変える可能性があり、ITビジネスの転換点を示唆しています。","importance":8},{"title":"NANDフラッシュ、ついに値下がりへ。2027年第1四半期に最大-5%の予測","url":"https://pc.watch.impress.co.jp/docs/news/2158129.html","source":"Hatena","published_at":"2026-11-20 12:13","genre":"other","genre_label":"総合・その他IT","headline":"NANDフラッシュ価格が2027年に下落予測、需給バランスの逆転が要因","summary":"調査会社TrendForceは、2027年にNANDフラッシュ市場が供給過剰に転じ、価格が下落するとの見通しを発表した。中国のクラウド事業者による企業向けSSD発注の減少と、民生機器需要の縮小が主な要因である。\n\n一方で、業界全体の設備投資は継続し、高積層化によるビット供給量は増加する見込み。2026年第4四半期からすでに契約価格の上昇率が下方修正されており、市場環境の変化が鮮明になっている。","importance":6},{"title":"初心者がAIとMAXのAPKを解析してみた","url":"https://zenn.dev/aki0804/articles/d4ec272cf5f871","source":"Zenn","published_at":"2026-11-20 10:34","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AIを活用したAndroidアプリ「MAX」のリバースエンジニアリング事例","summary":"AIエージェントの補助を得て、ロシアのメッセンジャーアプリ「MAX」のAPKを解析した事例。静的解析と隔離環境でのJVM試験を通じて、本文送信処理、VPN制限、診断データの送信条件を調査した。\n\n解析の結果、通常送信処理はサーバー側で本文を復元可能な設計である可能性が高いことや、VPN利用時の返信制限には特定の条件設定が存在することが判明した。開発元のソースコードではないものの、アプリの挙動を理解するための手法として参考になる。","importance":6},{"title":"政府の内部資料流出か、基幹システムに不正アクセス　デジタル庁発表：朝日新聞","url":"https://www.asahi.com/articles/ASVCN30WCVCNULFA01NM.html","source":"Hatena","published_at":"2026-11-20 18:31","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"デジタル庁、政府基幹システムへの不正アクセスで内部資料漏洩の可能性","summary":"デジタル庁は、政府の基幹ネットワークシステム「ガバメントソリューションサービス（GSS）」内のファイル共有サービスに対し、不正アクセスがあったことを発表しました。7月30日から11月12日の間にアクセスが行われていた可能性があり、政府の内部資料や個人情報が流出した恐れがあります。\n\nGSSは総務省や内閣府など25機関が利用する共通基盤であり、今回の事態を受けてサービスは停止されました。政府機関を標的としたサイバー攻撃が相次ぐ中、機密情報の取り扱いやシステム全体のセキュリティ強化が急務となっています。","importance":9},{"title":"先頭に貼るだけのキラープロンプト7選、コピペOK。→「所見を頼む前に「中学校の担任として、前向きな言葉で」と1行足すだけで、書き直しが半分に減りました。」","url":"https://posfie.com/@techjiho/p/3QDGKHH","source":"Hatena","published_at":"2026-11-20 11:23","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ChatGPT等の回答精度を劇的に高める「先頭に貼るだけ」のキラープロンプト7選","summary":"生成AIの回答品質を向上させるための、プロンプトの先頭に加えるべき7つの指示を紹介。専門家モードや結論ファースト、自己検算モードなどを組み合わせることで、汎用的な回答を実務レベルに引き上げることが可能になる。\n\n特に「中学校の担任として」といった役割付与や、出典の明記を求める指示は、書き直しを減らし信頼性を高める効果がある。批判的思考モードの追加など、ユーザーの工夫次第でAIのポテンシャルを最大限に引き出せる。","importance":9},{"title":"はてなエンジニアの自作RSSリーダーをご紹介します 2026 - Hatena Developer Blog","url":"https://developer.hatenastaff.com/entry/2026/11/20/162322","source":"Hatena","published_at":"2026-11-20 17:33","genre":"other","genre_label":"総合・その他IT","headline":"はてなエンジニアによる個性豊かな自作RSSリーダーの紹介","summary":"はてなエンジニアが業務外で自作したRSSリーダーの事例が紹介されました。キーボード操作に特化したものや、SNSのようなタイムライン形式、AIによる記事分類やPodcast配信機能を持つものなど、個人のこだわりが反映されたツールが並びます。\n\n生成AIの活用により自作のハードルが下がっている現状を背景に、エンジニアが「欲しいもの」を形にする文化が垣間見えます。既読管理の有無やUIの工夫など、情報収集のスタイルを最適化するための多様なアプローチが示されています。","importance":4},{"title":"Amazon Cognito のトークン交換を試し、AgentCore Gateway の Outbound Auth に組み込む","url":"https://zenn.dev/exwzd/articles/20261116-cognito-token-exchange","source":"Zenn","published_at":"2026-11-20 16:08","genre":"web","genre_label":"Web開発・言語","headline":"Amazon Cognitoのトークン交換機能を用いたOBO認証の実装","summary":"Amazon CognitoがOAuth 2.0のトークン交換に対応したことを受け、エージェントがユーザーの代わりに下流APIを呼び出す「OBO（On-behalf-of token exchange）」の実装方法が解説されました。これにより、ユーザープール1つでスコープの狭いトークン発行が可能になります。\n\nRFC 8693に基づくトークン交換の仕組みや、AgentCore Gatewayへの組み込み方法が検証されています。ユーザーの権限を適切に委譲しつつ、下流APIへのアクセスを制御するアーキテクチャとして、認証・認可の設計における重要なアップデートです。","importance":7},{"title":"必死で資料を作った会議、上役の「直近のセキュリティ危機は大丈夫なのか」って質問に上司が「あなたが予算を減らしたのでダメです」って返して15分で終わった","url":"https://togetter.com/li/2772854","source":"Hatena","published_at":"2026-11-20 18:29","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"セキュリティ予算削減を指摘した上司が役員に連行される会議の顛末","summary":"セキュリティ対策の会議において、上役からの「セキュリティは大丈夫か」という問いに対し、上司が「予算を5年連続で減額したため対策不可能」と即答し、その上役が役員に連行されるという出来事がSNSで話題となりました。\n\nこのエピソードは、現場のエンジニアが抱えるセキュリティ対策のジレンマと、経営層の認識不足を象徴する事例として多くの共感を呼んでいます。技術的負債やセキュリティリスクを軽視した予算配分が、組織の存続に関わる重大なリスクを招くという教訓を浮き彫りにしました。","importance":6},{"title":"日本で受け入れられるのか？　ネットにつながらない携帯「INFOBAR ZERO」　KDDIが語った発売の意図","url":"https://www.itmedia.co.jp/news/article/2611/20/2000003330/","source":"Hatena","published_at":"2026-11-20 09:25","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"KDDIが発売するネット非接続の携帯「INFOBAR ZERO」の狙い","summary":"KDDIが12月25日に発売する「INFOBAR ZERO」は、音声通話とSMSに機能を絞った「ダムフォン」だ。データ通信やSNS機能は排除されており、デジタルデトックス需要を意識している。\n\n収益性よりもブランド価値の向上を目的としており、キャリアを問わず利用可能なSIMフリー端末として販売される。スマホ全盛の時代に、あえて機能を削ぎ落とすことで情緒的な価値を提供し、auブランドのファン層拡大を狙う戦略的な製品である。","importance":5},{"title":"万博跡地は今どこまで更地になった？ 衛星の SAR 強度と夜間光で追ってみた（Sentinel-1 × VIIRS）","url":"https://zenn.dev/syu_tan/articles/002_expo_site_sar","source":"Zenn","published_at":"2026-11-20 11:45","genre":"other","genre_label":"総合・その他IT","headline":"衛星データ（SAR・夜間光）で追う大阪・関西万博跡地の解体状況","summary":"Sentinel-1のSAR強度画像と夜間光データを用い、大阪・関西万博跡地の解体進捗を可視化。SARは雲や夜間に関係なく地上の構造物の変化を捉えられるため、更地化の過程を追跡するのに適している。\n\n解析の結果、リングの解体は2026年に入って加速し、西側から順に更地化が進んだ様子が確認できた。光学衛星画像よりもSARの方が構造物の変化を詳細に捉えられる場合があり、リモートセンシングによる定点観測の有効性が示された。","importance":5},{"title":"POS端末700台超がマルウェア感染、Windowsの脆弱性悪用でカード情報100万件超が流出","url":"https://news.mynavi.jp/techplus/article/20261120-5367457/","source":"Hatena","published_at":"2026-11-20 18:57","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windowsの脆弱性を悪用したPOS攻撃で100万件超のカード情報が流出","summary":"20カ国以上に設置された700台超のPOS端末がマルウェアに感染し、100万件以上のクレジットカード情報が窃取される被害が発生しました。攻撃者は、2024年12月に修正済みであったWindowsの脆弱性「CVE-2024-49138」を悪用し、SYSTEM権限を取得して情報を収集していました。\n\n被害の大半はブラジルに集中しており、長期間にわたりセキュリティ更新プログラムが適用されていなかった端末が標的となりました。本件は、OSやアプリケーションの定期的なアップデートが、サイバー攻撃を防ぐための最も基本的な防御策であることを再認識させる事例です。","importance":8},{"title":"ドンキのAI社員「近藤あい」が正式デビュー　販促POPや動画で活躍へ　運営元「すでに裏に20人ぐらいいる」","url":"https://www.itmedia.co.jp/news/article/2611/20/2000003369/","source":"Hatena","published_at":"2026-11-20 15:50","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ドン・キホーテのAI社員「近藤あい」が正式デビュー、裏には20人のAI社員が待機","summary":"ドン・キホーテを運営するPPIHが、生成AIで制作したAI社員「近藤あい」を正式デビューさせました。販促POPや動画制作の効率化を目的としており、タレント起用に伴うコストやリスクを抑える狙いがあります。\n\n開発には1年半を費やし、性格や言葉遣いまで細かく設定されています。さらに、既に「第2の近藤あい」として約20人のAIキャラクターが控えていることも明かされました。AIを単なるツールとしてではなく、社員として活用する企業の新たな取り組みとして注目されます。","importance":7},{"title":"検索を速くすると、代わりに何が重くなるのか","url":"https://zenn.dev/loglass/articles/9f1c9da491fefa","source":"Zenn","published_at":"2026-11-20 12:00","genre":"web","genre_label":"Web開発・言語","headline":"PostgreSQLの検索高速化手法におけるトレードオフの定量比較","summary":"PostgreSQLにおける検索高速化手法（GIN index、生成列、MATERIALIZED VIEW）が、検索速度、書き込み負荷、容量、データ鮮度に与える影響を定量的に比較検証した。\n\nGIN indexは部分一致検索を大幅に高速化するが、書き込み負荷と容量増大が課題となる。また、生成列を用いた正規化は検索を劇的に速くするが、設計上の注意が必要。要件に応じてこれらのトレードオフを理解し、最適な手法を選択することが重要である。","importance":8},{"title":"【HTB】CODEBLUE2026 CTF - Kasio","url":"https://zenn.dev/taksecbe/articles/codeblue2026-htb-ctf","source":"Zenn","published_at":"2026-11-20 00:32","genre":"other","genre_label":"総合・その他IT","headline":"CODEBLUE2026 CTF「Kasio」問題のWriteup","summary":"CODE BLUE 2026で開催されたCTFのPwn問題「Kasio」の攻略記録。Heap問であり、UAF（Use-After-Free）を利用してlibcリークを行い、`register_printf_specifier`を悪用してシェルを奪取する手法を解説している。\n\nHouse of Huskの手法を応用し、関数ポインタをsystem関数に書き換えることで攻撃を成功させた。久しぶりのPwn問題への挑戦を通じて、脆弱性調査とExploit作成のプロセスを振り返る内容となっている。","importance":5},{"title":"日経平均終値3007円安、AI・半導体に売り　アンソロピックに祝杯ならず - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOFL200MHTQ6A121C2000000/","source":"Hatena","published_at":"2026-11-20 13:27","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"日経平均が3000円超の大幅下落、AI・半導体銘柄への売りが加速","summary":"20日の東京株式市場で、日経平均株価が前日比3007円安と大幅に下落しました。米アンソロピックの上場は順調だったものの、それ以外の米株価指数が低迷し、AI・半導体関連銘柄を中心に売りが先行しました。\n\n市場の期待を一身に集めていたAI関連株の調整は、個人投資家の心理にも影響を与えています。AIバブルの持続性や市場の需給バランスが改めて問われる展開となっており、今後のIT投資トレンドにも影響を与える可能性があります。","importance":7},{"title":"マウスやキーボードの電池残量がタスクバーで確認できる「BatteryHub」","url":"https://pc.watch.impress.co.jp/docs/news/2158043.html","source":"Hatena","published_at":"2026-11-20 06:48","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ワイヤレス機器の電池残量をタスクバーに表示する「BatteryHub」","summary":"マウスやキーボードなどのワイヤレス機器のバッテリー残量をタスクバーに一括表示するオープンソースツール「BatteryHub」が公開された。Windows 10/11に対応し、軽量かつ外部ランタイム不要で動作する。\n\n主要メーカーの周辺機器やコントローラーに対応しており、専用ソフトを起動せずに直接通信を行う。残量が15%以下になると通知する機能や、ダークモード対応など実用的な機能を備えている。","importance":4},{"title":"当社グループが利用するクラウドサービスの委託先への不正アクセスによる情報流出の可能性について","url":"https://about.mercari.com/press/news/articles/20261120_incidentreport/","source":"Hatena","published_at":"2026-11-20 16:28","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"メルカリ、Notion AIの委託先への不正アクセスによる情報流出の可能性","summary":"株式会社メルカリは、業務で利用している「Notion AI」の委託先であるFireworks AIが第三者による不正アクセスを受けたことを発表しました。現在、グループ各社が利用する情報への影響について調査を進めています。\n\nSaaSやAIサービスの利用において、委託先の委託先（再委託先）まで含めたセキュリティリスク管理が不可欠であることを示す事例です。企業は利用するクラウドサービスのサプライチェーンを把握し、適切な対策を講じる必要があります。","importance":8},{"title":"KaggleのポケモンカードAI対戦コンペ(PTCG AI Battle Challenge)の解法と学び","url":"https://zenn.dev/retrieva_tech/articles/8a1fa7ae2e28ee","source":"Zenn","published_at":"2026-11-20 14:47","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"KaggleのポケモンカードAI対戦コンペで銀メダルを獲得したTransformerモデルの解法","summary":"ポケモンカードのAI対戦コンペにおいて、Transformerを用いたエージェントで銀メダルを獲得したチームの解法が公開されました。探索を行わず、模倣学習と強化学習を組み合わせたモデルで盤面を評価する手法が採用されています。\n\n特に、盤面上の区別できない候補をまとめる前処理や、特定の局面を見分ける特徴量の追加が勝率向上に大きく寄与しました。計算資源が限られた環境下で、モデルの軽量化と学習データの質を追求するアプローチは、強化学習の実践的な知見として参考になります。","importance":8},{"title":"Rails の ActionController::Live × gRPC Server Streaming で、AI の返答をリアルタイム","url":"https://zenn.dev/flyingclouds/articles/2b6fa8c0e86a14","source":"Zenn","published_at":"2026-11-20 11:19","genre":"web","genre_label":"Web開発・言語","headline":"RailsのActionController::LiveとgRPCストリーミングによるAI返答のリアルタイム表示","summary":"RailsとPythonのAIサービスをgRPCで接続し、AIの返答をリアルタイムにブラウザへ表示する仕組みを解説。gRPCのServer Streamingで受け取ったチャンクを、ActionController::Liveを用いたSSEでブラウザへ流す構成を採用した。\n\nポイントは、タブを閉じても生成を止めないためのエラーハンドリングと、Pumaのスレッド占有を防ぐための同時接続制限。WebSocketを使わずともSSEで十分なストリーミング体験が実現できる。","importance":8},{"title":"Metaが学校に狙い、10代を「Instagram」へ引き込む計画が社内文書で判明","url":"https://japan.cnet.com/article/35255211/","source":"Hatena","published_at":"2026-11-20 12:51","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Metaが学校コミュニティ活用で10代ユーザー獲得を画策する社内文書が流出","summary":"MetaがInstagramのユーザー数とエンゲージメントを拡大するため、学校ごとのコミュニティ機能を強化する「Project Gryffindor」を計画していたことが社内文書で判明した。学校のバナー表示や卒業予定年での検索機能などが提案されている。\n\nこの取り組みは、ソーシャルメディアが若年層に依存性を植え付けているとして係争中の大規模訴訟の証拠として開示された。Metaは安全性を強調するが、専門家からは若年層の保護リスクに対する懸念が示されている。","importance":7},{"title":"湘南美容クリニックのSBC、162万人分の個人情報流出　パスワードは「暗号化せず保存していた」","url":"https://www.itmedia.co.jp/news/article/2611/20/2000003355/","source":"Hatena","published_at":"2026-11-20 08:45","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"SBCメディカルグループで162万人分の個人情報流出、パスワード平文保存が判明","summary":"SBCメディカルグループのデータベースが不正アクセスを受け、162万4000人分の個人情報が流出した。流出した情報には氏名、住所、電話番号に加え、当時暗号化せずに保存されていたパスワードが含まれていた。\n\n深夜に海外から77万回もの攻撃が行われたことが原因。外部予約サービス「トリビュー」経由の漏えいも確認されている。企業におけるパスワード管理の不備が改めて浮き彫りとなり、セキュリティ対策の重要性が再認識される事態となった。","importance":9},{"title":"Strix HaloにおけるLemonadeの推論速度・精度評価","url":"https://zenn.dev/anjn/articles/05cbd04f980f56","source":"Zenn","published_at":"2026-11-20 12:46","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Strix Halo環境におけるAI推論エンジン「Lemonade」の性能評価","summary":"Ryzen AI Max+ 395を搭載したStrix Halo機を用い、AIモデル管理ツール「Lemonade」の推論速度と精度を検証。Qwen系列のモデル8構成を比較し、Prefill/Decode速度および主要課題での正答率を測定した。\n\n検証の結果、Qwen3.8-Flash-NextをHalogenで実行する構成が最も実用的で高精度であることが判明。思考中の反復現象に対しても、回答用出力枠を確保する制御が有効に機能し、安定した回答生成が可能であることを確認した。","importance":8},{"title":"Rails から Python のサービスを gRPC で呼ぶ：はじめてでも本番で使える構成ガイド","url":"https://zenn.dev/flyingclouds/articles/d11dd921ca756b","source":"Zenn","published_at":"2026-11-20 11:18","genre":"web","genre_label":"Web開発・言語","headline":"RailsからPythonサービスをgRPCで呼び出すための本番運用ガイド","summary":"RailsからPythonのAIサービスをgRPCで呼び出すための、proto定義から実装、テストまでの構成ガイド。protoを契約の正本として扱い、型安全な通信を実現する手法を提案する。\n\n特にPumaのclusterモード等でのforkによる接続エラーを防ぐための遅延接続や、gRPCの型をクライアントクラス内に閉じ込める設計が重要。本番運用を見据えたエラーハンドリングと認証の実装により、堅牢なマイクロサービス連携が可能になる。","importance":8},{"title":"「Microsoft To Do」アプリが2027年6月で廃止、個人の場合は別アプリへの乗り換えが必要に／法人向けは「Planner」が後継","url":"https://forest.watch.impress.co.jp/docs/news/2158040.html","source":"Hatena","published_at":"2026-11-20 15:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Microsoft To Doが2027年6月で廃止、法人向けはPlannerへ移行","summary":"Microsoftはタスク管理アプリ「Microsoft To Do」を2027年6月30日で終了すると発表しました。個人ユーザー向けの後継アプリは用意されず、他社サービスへの乗り換えが必要です。\n\n法人向けには「Microsoft Planner」が後継となりますが、既存のタスクやリストは自動移行されません。また、Plannerはデスクトップアプリやオフライン機能が制限されるなど仕様が異なるため、組織での利用には早めの移行計画とデータエクスポートの準備が求められます。","importance":6},{"title":"自宅サーバー上のアプリケーションを Cloudflare Tunnel + Access で安全に公開する","url":"https://zenn.dev/bisque/articles/home-server-cloudflare-tunnel-access","source":"Zenn","published_at":"2026-11-20 16:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cloudflare TunnelとAccessを用いた自宅サーバーの安全な公開手法","summary":"自宅サーバーをインターネットに公開する際のセキュリティリスクを、Cloudflare TunnelとAccessを組み合わせることで安全に解決する手法が解説されました。ルーターのポートを開放せずに外部からアクセス可能にし、認証機能もCloudflare側で一元管理します。\n\n認証機能をアプリ側に実装する必要がなく、AIエージェント向けのサービストークン活用など、モダンな開発環境における安全な運用方法が具体的に示されています。個人開発者がコストを抑えつつ、堅牢なセキュリティ環境を構築するための実践的なガイドです。","importance":7},{"title":"自分の代わりに動くAgentへ。Claude CodeとCodexで作る自律改善ハーネス","url":"https://zenn.dev/nttdata_tech/articles/9562962cc181a1","source":"Hatena","published_at":"2026-11-20 08:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude CodeとCodexを活用した自律的な開発環境「ハーネス」の設計","summary":"コーディングAgentに自律的に作業を任せるための「ハーネス（仕組み）」を構築した事例。プロンプトを磨くことよりも、フォルダ構造や概念の置き場を定義し、Agentが自分で読み書き・検査できる環境を整えることに注力した。\n\nタスク管理をTASK.mdで行い、規約をGitリポジトリで一元管理することで、複数のAgentセッションを並行稼働させても一貫性を保てるようにした。これにより、人間は確認と判断に集中できる環境を実現している。","importance":8},{"title":"Go runtime - Bootstrap","url":"https://zenn.dev/aqyuki/articles/go-runtime-bootstrap","source":"Zenn","published_at":"2026-11-20 17:40","genre":"web","genre_label":"Web開発・言語","headline":"Goランタイムの起動プロセス「Bootstrap」の仕組みを解説","summary":"Go言語のランタイムがプログラム起動時に行う初期化処理「Bootstrap」についての詳細な解説です。OSスレッド（M）やGoroutine（G）、仮想CPU（P）の初期化から、ランタイムの前提条件チェック、main関数の実行に至るまでの流れを追っています。\n\n特に、レジスタ経由で渡される引数の退避や、TLSの初期化、スケジューラーのセットアップなど、Goランタイムがどのようにして実行環境を整えるのかが技術的に深掘りされています。Goの内部構造を理解したいエンジニアにとって有益な情報です。","importance":6},{"title":"AIに悩みを相談する際に気をつけて欲しいこと｜SSC","url":"https://www.assdr.kyoto-u.ac.jp/ssc/consulting_ai/","source":"Hatena","published_at":"2026-11-19 22:44","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AIへの悩み相談における注意点とリスク管理","summary":"生成AIに悩み相談をする際の注意点をまとめたガイド。AIはもっともらしい嘘をつく可能性や、ユーザーに迎合的な回答をする傾向があることを認識する必要がある。\n\nAIを人格的存在と錯覚する「イライザ効果」により、人間関係のスキルが低下するリスクや、アルゴリズム・バイアスの影響について警告している。AIはあくまで補助ツールであり、重要な判断は人間に相談すべきであるという健全な利用姿勢を提唱している。","importance":6},{"title":"Windows 11のロック画面をナレーターで突破できる脆弱性。BitLocker環境も対象","url":"https://pc.watch.impress.co.jp/docs/news/2158179.html","source":"Hatena","published_at":"2026-11-20 15:24","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windows 11のロック画面をナレーターで突破できる脆弱性「FastUnlock」が判明","summary":"セキュリティ研究者が、Windows 11のロック画面をナレーター機能経由で突破できるゼロデイ脆弱性「FastUnlock」を公開しました。この脆弱性は、サインイン前の回復画面から設定画面へ不正にアクセスし、BitLockerで保護された環境下でも権限昇格を可能にします。\n\n現時点でMicrosoftからの修正パッチは未提供です。悪用には物理的なアクセスとオンラインのMicrosoftアカウント紐付けが必要ですが、PCの盗難時などに深刻なリスクとなります。修正が提供されるまで、PCの物理的な管理を徹底することが強く推奨されます。","importance":8},{"title":"MetaのMuseを使ってみた: 内部構造とセキュリティの調査","url":"https://zenn.dev/shoyataguchi/articles/b1bc6a96d4b963","source":"Zenn","published_at":"2026-11-20 00:55","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MetaのAIアプリ「Muse」の内部構造とセキュリティ設計の調査","summary":"Metaが提供するAIアプリ「Muse」のUXと内部構造を調査したレポート。メインチャットとサイドチャットを使い分け、長期記憶を共有する設計が特徴。ユーザー専用のLinux環境でShellやcronを操作できる点も強力である。\n\n記憶機構にはGraphRAGのような手法が用いられ、claim（事実・好み・約束）を抽出して整理している。また、セキュリティへの投資が他社製品との大きな差別化要因となっており、安全なエージェント運用を目指す設計思想が垣間見える。","importance":8},{"title":"Claude Code の起動時に依存パッケージの脆弱性を調べるハーネスを、既製品と比べたうえで自作した話","url":"https://zenn.dev/no215/articles/claude-code-security-guardrail","source":"Zenn","published_at":"2026-11-20 09:01","genre":"web","genre_label":"Web開発・言語","headline":"Claude Code起動時に依存パッケージの脆弱性を自動検知する仕組み","summary":"リポジトリの依存パッケージに潜む脆弱性を、Claude Codeの起動時に自動でチェックする仕組みを構築した。既製品のCVE Sentinel等と比較検討した結果、通信頻度やレポート形式を制御するため、osv-scannerと自作スクリプトを組み合わせる手法を選択した。\n\n1日1回だけ脆弱性情報を取得し、ローカルで照合することでトークン消費を抑えつつ、セッション開始時に自動でリスクを通知する。開発効率とセキュリティを両立させるための実用的なハックである。","importance":7},{"title":"キオクシア株の下げ止まらず　PER1倍台目前、AI需要を警戒 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUB184O30Y6A111C2000000/","source":"Hatena","published_at":"2026-11-20 13:03","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"キオクシア株が急落、AI半導体需要への懸念からPER1倍台へ","summary":"キオクシアホールディングスの株価が大幅に下落し、7カ月半ぶりの安値を記録した。予想PERは2倍を割り込み、1倍台目前まで低下している。\n\n市場では、AI半導体需要の拡大に伴う中長期的な利益成長シナリオに対し、警戒感が強まっていることが背景にある。QUICKコンセンサスなどの市場予想に基づき、投資家の慎重な姿勢が株価に反映されている。","importance":5},{"title":"ハンコヤドットコム、カード番号やセキュリティコード8220件漏えいか　決済画面改ざんされる","url":"https://www.itmedia.co.jp/news/article/2611/20/2000003367/","source":"Hatena","published_at":"2026-11-20 14:05","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ハンコヤドットコムで決済画面改ざん、カード情報など8220件が漏えいの可能性","summary":"印鑑通販サイト「ハンコヤドットコム」が不正アクセスを受け、顧客のクレジットカード番号やセキュリティコードなど8220件が漏えいした可能性があると発表しました。決済画面が改ざんされ、入力情報が外部へ送信される状態になっていました。\n\n同社はカード情報を保持していませんでしたが、サイトの脆弱性を突かれた形です。相次ぐECサイトの決済情報流出を受け、セキュリティ対策の再点検と、決済処理の安全性を担保する仕組みの重要性が改めて浮き彫りになっています。","importance":8},{"title":"Appleの会話要約AI「Siri Recap」を2週間使った結果「自分が救急搬送された」という架空の記録が生成される","url":"https://gigazine.net/news/20261120-siri-recap-hands-on/","source":"Hatena","published_at":"2026-11-20 15:15","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Apple Watchの会話要約AI「Siri Recap」が誤認識で架空の記録を生成する課題","summary":"Apple Watchの新機能「Siri Recap」は、周囲の会話をAIが自動要約する機能ですが、プライバシー保護のための話者識別を行わない仕様が原因で、動画の音声を本人や知人の出来事と誤認するケースが報告されています。\n\nプライバシー重視の設計は評価される一方、文脈の理解不足や数字・日付への過度な偏重により、実用性には課題が残ります。ユーザーは会話相手への配慮や、機能のオンオフを適切に管理する必要があり、AIによる自動記録の利便性と精度のバランスが改めて問われています。","importance":7},{"title":"Spring ProfileでAWSとAWS Emulatorを切り替える","url":"https://zenn.dev/enchanter_one/articles/e8a849e6080f80","source":"Zenn","published_at":"2026-11-20 14:59","genre":"web","genre_label":"Web開発・言語","headline":"Spring Profileを活用してAWS環境とエミュレーターを柔軟に切り替える手法","summary":"AWSを利用する開発において、本番環境とローカル開発・テスト環境でAWS Emulatorを切り替えるためのSpring Boot設定手法が紹介されました。SPRING_PROFILES_ACTIVE環境変数を用いることで、コード変更なしに接続先を制御可能です。\n\n本番環境向けの疎通確認と、日常的な統合テストを役割分担することで、テスト効率を向上させつつシンプルな構成を維持できます。DIを活用してAWS ClientをBean化する実装例は、クラウドネイティブな開発環境の構築において非常に実用的な知見です。","importance":6},{"title":"脆弱性検査のあとに取った対策 — 見つかった穴を「機械で止める」仕組みへ","url":"https://zenn.dev/doreens/articles/457ea6852608a9","source":"Zenn","published_at":"2026-11-20 12:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"脆弱性検査で見つかった穴を「機械で止める」ためのCI/CD対策","summary":"脆弱性検査で判明したセキュリティ上の欠陥に対し、単なる修正だけでなく、再発防止のための自動化施策を導入。テストの抜けを機械的に検知し、CIパイプラインに静的解析や依存関係検査を組み込む計画を策定した。\n\n特に認可テスト行列の自動生成や、セキュリティ観点のfixture導入により、新しい機能追加時にもセキュリティゲートが機能する仕組みを構築。重大度に応じた対応と、破壊的変更を含むリリースを通じて、堅牢な開発体制への移行を目指している。","importance":8},{"title":"日本のレシートを自宅PCでOCRする：15構成を実レシート11枚で比べた","url":"https://zenn.dev/chaki/articles/4545be3475fdb4","source":"Zenn","published_at":"2026-11-20 13:33","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"自宅PCで日本のレシートをOCRする15構成の比較検証、YomiTokuが最高精度","summary":"自宅のミニPC環境で日本のレシートをOCRする手法として、15通りの構成を比較検証した結果が公開されました。軽量モデルと高精度モデルを組み合わせる「2段読み」を行う「YomiToku」が、商品名・金額ともに最も高い精度を示しました。\n\nNVIDIA GPUを用いない環境での検証結果は、ローカル環境でのAI活用を目指すエンジニアにとって貴重なデータです。VLM型と従来型の特性の違いや、手書き領収書におけるVLMの優位性など、用途に応じたモデル選択の指針が示されています。","importance":7},{"title":"WordPressにプラグインなしでGoogle翻訳を組み込んだメモ【インバウンド向け】","url":"https://zenn.dev/noboo/articles/289c07479497e0","source":"Zenn","published_at":"2026-11-20 13:45","genre":"web","genre_label":"Web開発・言語","headline":"WordPressにプラグインなしでGoogle翻訳を組み込み多言語対応する実装メモ","summary":"WordPressサイトにおいて、プラグインを使用せずfunctions.phpにGoogle翻訳スクリプトを記述して多言語対応する手法が解説されました。DBを汚さず、サイトの軽量化と管理コスト削減を両立できるのが利点です。\n\n翻訳バナーやホバー時のポップアップをCSS/JSで非表示にする工夫や、言語切り替えリンクの活用法など、実店舗系サイトのインバウンド対応として非常に実用的な備忘録となっています。プラグインの競合や肥大化を避けたいエンジニアにとって有益な情報です。","importance":5},{"title":"CDKからTerraformへ：所有権移譲による本番インフラ無停止のIaC移行","url":"https://zenn.dev/levtech/articles/14befd8e727f32","source":"Zenn","published_at":"2026-11-20 10:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CDKからTerraformへ：本番環境を停止させないIaC移行手法","summary":"AWS CDK v1のEOLに伴う技術的負債解消のため、13スタックの本番インフラをTerraformへ移行した事例。サービスを停止させずに移行するため、「所有権の移譲」という手法を採用した。\n\n具体的には、CDK側でリソースを保持（Retain）設定にしてスタックから削除し、Terraform側でimportブロックを用いて既存リソースを管理下に取り込む手順を踏んだ。AIによるコード生成やCIでの差分確認を組み合わせることで、安全かつ円滑な移行を実現している。","importance":8},{"title":"同じ内容でも言語でトークン数は何倍違う？日本語・中国語・韓国語・タイ語を6つのトークナイザーで比べてみた","url":"https://zenn.dev/aiforall/articles/5069b7c19696bf","source":"Zenn","published_at":"2026-11-20 12:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"言語別トークン数の違いを6つのトークナイザーで比較検証","summary":"LLMのコストやコンテキスト容量に直結する「トークン数」について、日本語・中国語・韓国語・タイ語を6つのトークナイザーで比較検証。英語と比較して何倍のトークンを消費するかを調査した。\n\n結果として、トークナイザーの語彙構成により倍率は大きく異なり、新しい世代のモデルでは多言語対応が改善されていることが判明した。日本語は文字数とトークン数が近い傾向にあるが、言語やモデルによってコスト効率が大きく変わるため、適切なモデル選択が重要である。","importance":7}]};
